function combinations(fields) {
  return fields.reduce((p, n) => p * n, 1);
}

function hotSpots(defectsByModule, share) {
  const rows = Object.entries(defectsByModule).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  const total = rows.reduce((s, r) => s + r[1], 0);
  if (total === 0) return [];
  const out = [];
  let sum = 0;
  for (const [name, n] of rows) {
    out.push(name);
    sum += n;
    if (sum + 1e-9 >= share * total) break;
  }
  return out;
}
